function makeRelic(used=new Set()){const choices=relicCatalog.filter(relic=>!used.has(relic.name)),base={...(pick(choices.length?choices:relicCatalog))};return {id:`relic-${Math.floor(Math.random()*1e12).toString(36)}`,slot:'relic',kind:null,rarity:3,shopOnly:true,shopPrice:180,...base,armor:base.armor||0,attack:base.attack||0,crit:base.crit||0,leech:base.leech||0};}
