function tone(freq=220,duration=.07,type='triangle',volume=.03){if(!soundEnabled)return;try{audio??=new AudioContext();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.6,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function log(text){logs.unshift(text);logs=logs.slice(0,5);$('log').replaceChildren(...logs.map(t=>{const el=document.createElement('p');el.textContent=t;return el;}));}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');toastTime=2.5;}
function banner(text){$('wave-banner').textContent=text;$('wave-banner').classList.add('show');bannerTime=2.7;}
function textEffect(x,y,text,color='#efce91'){effects.push({type:'text',x,y,text,color,life:.9,max:.9});}
function burst(x,y,color,n=10){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),speed=rand(45,185),life=rand(.28,.75);effects.push({type:'particle',x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed-25,size:rand(2,5),glow:i%3===0,color,life,max:life});}}
function ring(x,y,r,color,width=3){effects.push({type:'ring',x,y,r,color,width,life:.55,max:.55});}
function rune(x,y,r,color){effects.push({type:'rune',x,y,r,color,angle:rand(0,Math.PI*2),life:.75,max:.75});}
function flash(color='#f7e4b1',strength=.16){screenFlash=Math.max(screenFlash,strength);screenFlashColor=color;}
function openModal(type,html){if(currentModal==='talent'&&modal.open&&type!=='talent'&&type!=='result')return;if(type==='start')running=false;currentModal=type;paused=true;held=false;keys.clear();$('modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();currentModal='';if(running&&!finished)paused=false;canvas.focus();}
function canAct(){return running&&!paused&&!finished&&!cinematic;}
function itemIcon(item){return item.slot==='weapon'?weaponInfo[item.kind].symbol:item.slot==='armor'?'⛨':item.slot==='relic'?'✥':'◈';}
function skillInfoFor(name){return classSkills[p.equipment.weapon.kind]?.[name]||skillInfo[name];}
function weaponColor(item=p.equipment.weapon){return rarities[item?.rarity||0]?.color||'#b8c8bb';}
function weaponImpact(x,y,item=p.equipment.weapon){const rarity=item?.rarity||0,color=weaponColor(item);burst(x,y,color,[3,7,12,18,28,42][rarity]);if(rarity>=1)ring(x,y,18+rarity*7,color,1+rarity);if(rarity>=2)ring(x,y,12+rarity*5,'#ffffff',1);if(rarity>=3)rune(x,y,24+rarity*7,color);if(rarity>=4){ring(x,y,58,'#fff2ad',4);flash(color,.07);screenShake=Math.max(screenShake,3);}if(rarity>=5){ring(x,y,82,'#fff8d0',5);rune(x,y,66,'#d49b32');flash('#fff0a6',.13);screenShake=Math.max(screenShake,6);}}
function weaponAttackEffect(item=p.equipment.weapon){const rarity=item?.rarity||0,color=weaponColor(item),kind=item?.kind||'sword';if(rarity>=1)burst(p.x+Math.cos(p.facing)*20,p.y+Math.sin(p.facing)*20,color,4+rarity*3);if(rarity>=2)ring(p.x,p.y,22+rarity*7,color,rarity);if(rarity>=3)rune(p.x,p.y,30+rarity*5,color);if(rarity>=4){ring(p.x,p.y,62,'#fff0a6',4);ring(p.x,p.y,86,color,2);flash('#ffd66e',.055);}if(rarity>=5){ring(p.x,p.y,108,'#fff8cf',5);rune(p.x,p.y,76,'#d69d32');burst(p.x,p.y,'#fff0a6',30);flash('#fff4c2',.11);}if(kind==='staff'&&rarity>=2)ring(p.x+Math.cos(p.facing)*25,p.y+Math.sin(p.facing)*25,18+rarity*3,color,2);}
function firePlayerShot(angle,damage,weapon=p.equipment.weapon,magic=weapon.kind==='staff'){const color=weaponColor(weapon),rarity=weapon?.rarity||0;shots.push({x:p.x,y:p.y,vx:Math.cos(angle)*(460+rarity*18),vy:Math.sin(angle)*(460+rarity*18),r:(magic?7:5)+Math.floor(rarity/2),life:3.2,damage,crit:false,friendly:true,magic,weapon,color,rarity});}
function leechDifficultyMultiplier(){return difficulty==='hard'?1:2.5;}
function effectiveLeech(raw){return raw*.5*leechDifficultyMultiplier();}
function itemStats(item){return [item.attack?`攻击 +${item.attack}`:'',item.armor?`护甲 +${item.armor}`:'',item.crit?`暴击 +${item.crit}%`:'',item.leech?`命中吸血 ${effectiveLeech(item.leech).toFixed(effectiveLeech(item.leech)%1?1:0)}%`:'',item.passiveText||'',item.enhance?`强化 +${item.enhance}`:''].filter(Boolean).join(' · ');}
function compare(item){const old=p.equipment[item.slot];return ['attack','armor','crit','leech'].map((key,i)=>{let delta=item[key]-(old?.[key]||0);if(key==='leech')delta=effectiveLeech(delta);return delta?`${['攻击','护甲','暴击','吸血'][i]} ${delta>0?'+':''}${Number.isInteger(delta)?delta:delta.toFixed(1)}${i>1?'%':''}`:'';}).filter(Boolean).join(' / ')||'属性相同';}
function itemCard(item,index,context){const sell=price(item,true);return `<div class="item-card ${item.golden?'golden-item':''} ${item.supreme?'supreme-item':''} ${item.blackMarket?'black-market-item':''}" style="--item:${rarities[item.rarity].color}"><strong>${itemIcon(item)} ${item.name}${item.enhance?` +${item.enhance}`:''}</strong><p>${rarities[item.rarity].name} · ${itemStats(item)}<br>相比已装备：${compare(item)}</p>${context==='buy'?`<button data-buy="${index}" ${p.gold<price(item)?'disabled':''}>购买 · ${price(item)} 金</button>`:`<button data-equip="${index}">装备</button>${context==='sell'?`<button data-sell="${index}">出售 · ${sell} 金</button>`:''}`}</div>`;}
function price(item,sell=false){const value=item.shopPrice||22+item.rarity*22+(item.enhance||0)*20;return Math.round(value*(sell?.42:1));}
function normalizeProfile(value={}){const result={...defaultProfile,purchases:{}};for(const key of ['diamonds','totalRuns','totalWins','totalKills','bestFloor','hardWins','throneFragments'])result[key]=Math.max(0,Number.isFinite(Number(value?.[key]))?Math.floor(Number(value[key])):0);result.finalThrone=Boolean(value?.finalThrone);if(value?.purchases&&typeof value.purchases==='object')for(const item of metaGoods)if(value.purchases[item.id])result.purchases[item.id]=true;return result;}
function markStorageFailure(error){storageState.available=false;storageState.error=error?.message||'浏览器拒绝访问本地存储';updateSaveStatus();}
function saveStatusText(){if(!storageState.available)return '⚠ 本地存档不可用 · 请立即导出备份';if(storageState.lastSavedAt)return `✓ 已自动保存 · ${new Date(storageState.lastSavedAt).toLocaleTimeString('zh-CN',{hour12:false})}`;return '✓ 本地存档已就绪';}
function updateSaveStatus(){const el=$('save-status');if(!el)return;el.textContent=saveStatusText();el.classList?.toggle('save-error',!storageState.available);}
function loadProfile(){try{const raw=localStorage.getItem(PROFILE_KEY);return normalizeProfile(raw?JSON.parse(raw):{});}catch(error){markStorageFailure(error);return normalizeProfile();}}
function saveProfile(reason='自动保存'){try{const serialized=JSON.stringify(profile);localStorage.setItem(PROFILE_KEY,serialized);localStorage.setItem(SETTINGS_KEY,JSON.stringify({difficulty}));if(localStorage.getItem(PROFILE_KEY)!==serialized)throw new Error('写入后无法读取存档');storageState.available=true;storageState.error='';storageState.warned=false;storageState.lastSavedAt=Date.now();updateSaveStatus();return true;}catch(error){markStorageFailure(error);if(!storageState.warned){storageState.warned=true;toast(`⚠ ${reason}失败：请在主界面导出存档备份`);}return false;}}
function saveBest(){if(!best)return true;try{localStorage.setItem(BEST_KEY,JSON.stringify(best));return true;}catch(error){markStorageFailure(error);return false;}}
function commitRunProgress(reason=`第 ${floor} 层第 ${wave} 场`){if(!p)return false;const delta=Math.max(0,(p.kills||0)-committedRunKills);if(delta){profile.totalKills+=delta;committedRunKills=p.kills;}profile.bestFloor=Math.max(profile.bestFloor,floor);return saveProfile(`${reason}自动保存`);}
function saveManagerMarkup(){return `<div class="save-tools"><button data-action="export-save">导出存档</button><button data-action="import-save">导入存档</button></div><p class="save-status ${storageState.available?'':'save-error'}">${saveStatusText()}</p>`;}
function throneMarkup(){if(profile.finalThrone)return '<div class="throne-panel throne-complete"><strong>♛ 最后的王座</strong><span>永久生效 · 后续对局全属性 +25%</span></div>';if(profile.throneFragments>0)return `<div class="throne-panel"><div><strong>♜ 王座碎片 ×${profile.throneFragments}</strong><span>可重铸最后的王座</span></div><button data-action="synthesize-throne">合成王座</button></div>`;return '<div class="throne-panel throne-locked"><strong>◇ 最后的王座</strong><span>击败第六层首领获得王座碎片</span></div>';}
function confirmThroneSynthesis(){if(profile.finalThrone||profile.throneFragments<1)return;openModal('throne-confirm','<div class="modal-eyebrow">THE FINAL THRONE</div><h2 class="modal-title">重铸最后的王座？</h2><p class="modal-subtitle">消耗 1 枚王座碎片。完成后，今后每次远征都会获得全属性 +25%。<br>各难度的普通战斗场数已经由本次补丁固定提升，不会因合成再次增加。</p><div class="modal-actions"><button data-action="main-menu">暂不合成</button><button class="primary" data-action="confirm-throne">重铸王座</button></div>');}
function synthesizeThrone(){if(profile.finalThrone||profile.throneFragments<1)return;profile.throneFragments--;profile.finalThrone=true;saveProfile('王座合成');tone(180,.7,'sawtooth',.05);startScreen();toast('最后的王座已经重铸：后续对局全属性 +25%！');}
function exportSave(){commitRunProgress('导出前');const payload={kind:'abyss-scavenger-save',version:1,exportedAt:new Date().toISOString(),profile:normalizeProfile(profile),best,difficulty};try{const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`abyss-scavenger-save-${new Date().toISOString().slice(0,10)}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0);toast('存档已导出，请妥善保管备份文件。');}catch(error){toast(`导出失败：${error?.message||'浏览器不支持下载'}`);}}
function chooseImportFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;input.addEventListener('change',async()=>{const file=input.files?.[0];input.remove();if(!file)return;try{if(file.size>1024*1024)throw new Error('存档文件超过 1MB');const data=JSON.parse(await file.text());if(data?.kind!=='abyss-scavenger-save'||!data.profile)throw new Error('这不是《深渊拾荒者》存档');pendingImport={profile:normalizeProfile(data.profile),best:data.best&&typeof data.best==='object'?data.best:null,difficulty:difficulties[data.difficulty]?data.difficulty:'easy'};openModal('confirm-import',`<div class="modal-eyebrow">RESTORE THE DESCENT</div><h2 class="modal-title">确认导入存档？</h2><p class="modal-subtitle">即将载入 ◆ ${pendingImport.profile.diamonds} 钻石、${pendingImport.profile.totalKills} 次击杀、${Object.keys(pendingImport.profile.purchases).length} 件永久升级。<br>当前本地进度将被这份备份替换。</p><div class="modal-actions"><button data-action="main-menu">取消</button><button class="primary" data-action="confirm-import">确认导入</button></div>`);}catch(error){toast(`导入失败：${error?.message||'文件损坏'}`);startScreen();}});document.body.append(input);input.click();}
function applyImportedSave(){if(!pendingImport)return;profile=normalizeProfile(pendingImport.profile);best=pendingImport.best;difficulty=pendingImport.difficulty;pendingImport=null;saveProfile('导入存档');saveBest();if(best&&Number.isFinite(best.kills))$('best').textContent=`本机纪录：${best.won?'已通关':`第 ${best.floor} 层`} · ${best.kills} 击杀`;startScreen();toast('存档导入成功。');}
function honorList(){return [{name:'初次下潜',desc:'完成第一场战斗',earned:profile.totalKills>0},{name:'穿越半途',desc:'抵达第三层',earned:profile.bestFloor>=3},{name:'王权见证者',desc:'抵达第六层',earned:profile.bestFloor>=6},{name:'深渊征服者',desc:'通关任意难度',earned:profile.totalWins>0},{name:'不屈拾荒者',desc:'累计击败 250 名敌人',earned:profile.totalKills>=250},{name:'无光凯旋',desc:'通关困难难度',earned:profile.hardWins>0}];}
function startScreen(){if(currentModal==='loadout'){loadoutScreen();return;}const earned=honorList().filter(h=>h.earned).length;openModal('start',`<div class="start-layout main-menu-layout"><div class="hero-showcase"><img src="./hero-gothic.png" alt="披甲的哥特拾荒者"><span>BLACK GOLD ALCHEMY</span></div><div class="start-copy"><div class="modal-eyebrow">THE DESCENT AWAITS</div><h2 class="modal-title">深渊拾荒者</h2><div class="menu-ledger"><span>◆ ${profile.diamonds} 钻石</span><span>${difficulties[difficulty].name}难度</span><span>${earned} / ${honorList().length} 荣誉</span></div><div class="main-menu-stack"><button class="main-menu-card main-menu-primary" data-action="new-run"><span class="menu-rune">†</span><span><strong>开始游戏</strong><small>选择兵器，进入完整六层远征</small></span><b>→</b></button><button class="main-menu-card" data-action="difficulty"><span class="menu-rune">◆</span><span><strong>选择难度</strong><small>当前：${difficulties[difficulty].name} · 每层 ${normalWaveCount()} 场普通战斗</small></span><b>→</b></button><button class="main-menu-card" data-action="honors"><span class="menu-rune">♜</span><span><strong>查看荣誉</strong><small>查看远征纪录与已解锁荣誉</small></span><b>→</b></button><button class="main-menu-card" data-action="meta-shop"><span class="menu-rune">✦</span><span><strong>商城</strong><small>使用钻石购买永久开局补给</small></span><b>→</b></button></div>${throneMarkup()}${saveManagerMarkup()}<p class="modal-note">每场战斗结束自动保存荣誉进度 · 钻石在整局结束时结算<br>主界面商城和局内商店相互独立</p></div></div>`);}
function loadoutScreen(){openModal('loadout',`<div class="start-layout"><div class="hero-showcase"><img src="./hero-gothic.png" alt="披甲的哥特拾荒者"><span>${difficulties[difficulty].name.toUpperCase()} DESCENT</span></div><div class="start-copy"><div class="modal-eyebrow">CHOOSE YOUR PATH · ${difficulties[difficulty].name}难度</div><h2 class="modal-title">选择起始兵器</h2><div class="story-window" aria-label="深渊序章"><div class="story-track"><p>灰潮吞没最后一座边境城后，<br>一束不属于人间的烛火在废墟下亮起。</p><p>六层被遗忘的王国沉睡于地底，<br>每一道门后，都有守墓者等待新的躯壳。</p><p>你带着一把旧兵器和无人认领的名字下行，<br>寻找黄金，也寻找深渊不愿归还的真相。</p><p class="story-last">烛火将熄。拾荒者，选择你的兵器。</p></div></div><div class="weapon-grid">${Object.entries(weaponInfo).map(([key,w])=>`<button class="weapon-choice ${key===chosen?'selected':''}" data-weapon="${key}"><span class="weapon-symbol">${w.symbol}</span><strong>${w.name}</strong><small>${key==='sword'?'近战横扫 · 攻速快<br>贴身战斗，打击多个目标':key==='bow'?'远程射击 · 灵活<br>保持距离，逐个击破':'奥术弹 · 范围爆炸<br>火力更强，攻击较慢'}</small></button>`).join('')}</div><button class="primary wide" data-action="start">踏入深渊 →</button><button class="wide" data-action="main-menu">返回主界面</button></div></div><p class="modal-note">WASD / 鼠标点击移动 · 点击敌人 / 空格攻击 · Shift / 1 / 2 技能<br>${difficulties[difficulty].name}难度每层 ${normalWaveCount()} 场普通战斗，再迎战首领。</p>`);}
function difficultyScreen(){openModal('difficulty',`<div class="modal-eyebrow">CHOOSE THE DESCENT</div><h2 class="modal-title">选择难度</h2><p class="modal-subtitle">新远征规则会随难度增加每层的普通战斗数量；完成全部普通战斗后才会出现首领。</p><div class="weapon-grid">${Object.entries(difficulties).map(([id,d])=>`<button class="weapon-choice ${difficulty===id?'selected':''}" data-difficulty="${id}"><span class="weapon-symbol">${id==='easy'?'◇':id==='normal'?'◆':'✦'}</span><strong>${d.name}</strong><small>${d.desc}<br>每层 ${normalWaveCount(id)} 场普通战斗 + 1 场首领战</small></button>`).join('')}</div><div class="modal-actions"><button class="primary" data-action="main-menu">确认并返回</button></div>`);}
function honorsScreen(){const honors=honorList();openModal('honors',`<div class="modal-eyebrow">HALL OF HONOR</div><h2 class="modal-title">拾荒者荣誉</h2><p class="modal-subtitle">累计远征 ${profile.totalRuns} 次 · 通关 ${profile.totalWins} 次 · 击败 ${profile.totalKills} 名敌人</p><div class="inventory-grid">${honors.map(h=>`<div class="item-card ${h.earned?'golden-item':''}"><strong>${h.earned?'◆':'◇'} ${h.name}</strong><p>${h.desc}<br>${h.earned?'已经获得':'尚未获得'}</p></div>`).join('')}</div><div class="modal-actions"><button class="primary" data-action="main-menu">返回主界面</button></div>`);}
function metaShopScreen(category=metaCategory){metaCategory=category;const categories={all:'全部',supply:'补给',body:'体魄',combat:'武技',arcane:'奥术',fortune:'财富'},items=category==='all'?metaGoods:metaGoods.filter(item=>item.category===category),ownedCount=metaGoods.filter(item=>profile.purchases[item.id]).length;openModal('meta-shop',`<div class="modal-eyebrow">BETWEEN DESCENTS · ${ownedCount} / ${metaGoods.length}</div><h2 class="modal-title">深渊商城 <span class="gold" style="font-size:21px">◆ ${profile.diamonds}</span></h2><p class="modal-subtitle">36 件永久升级分属五条成长路线。这里使用钻石，和局内金币商店完全独立。</p><div class="meta-filters">${Object.entries(categories).map(([id,name])=>`<button data-meta-category="${id}" ${category===id?'class="primary"':''}>${name}</button>`).join('')}</div><div class="inventory-grid meta-inventory">${items.map(item=>{const owned=profile.purchases[item.id];return `<div class="item-card ${owned?'golden-item':''}"><strong>✦ ${item.name}</strong><p>${item.desc}<br>${owned?'永久生效':categories[item.category]}</p><button data-meta="${item.id}" ${owned||profile.diamonds<item.cost?'disabled':''}>${owned?'已拥有':`购买 · ◆ ${item.cost}`}</button></div>`;}).join('')}</div><div class="modal-actions"><button class="primary" data-action="main-menu">返回主界面</button></div>`);}
function selectDifficulty(id){if(difficulties[id]){difficulty=id;saveProfile('难度设置保存');}return difficulty;}
function buyMeta(id){const item=metaGoods.find(g=>g.id===id);if(!item||profile.purchases[id]||profile.diamonds<item.cost)return;profile.diamonds-=item.cost;profile.purchases[id]=true;saveProfile();tone(680,.18);metaShopScreen(metaCategory);}
function applyMetaUpgrades(player){for(const item of metaGoods)if(profile.purchases[item.id])item.apply(player);if(profile.finalThrone){player.globalStatMultiplier=1.25;player.maxHp=Math.round(player.maxHp*1.25);player.hp=player.maxHp;player.maxMana=Math.round(player.maxMana*1.25);player.mana=player.maxMana;player.manaRegen*=1.25;}}
function start(){p=makePlayer(chosen);applyMetaUpgrades(p);p.artifacts=[];floor=1;wave=0;roomKind='ruins';map=createMap(1,roomKind);enemies=[];shots=[];effects=[];drops=[];hazards=[];path=[];target=null;elapsed=0;logs=[];pendingTalents=0;shopVisits=0;eliteNext=false;finished=false;runRewarded=false;committedRunKills=0;cinematic=null;lastBossDefeat=null;running=true;closeModal();log(`以${difficulties[difficulty].name}难度踏入苔影遗迹。愿火光照见归途。`);if(profile.finalThrone)log('最后的王座回应了你：本次远征全属性 +25%。');nextWave();updateUI();}
function safeEnemyPoint(origin,r=12){const choices=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++){const pos=center(x,y);if(walkable(map,pos.x,pos.y,r)&&distance(p,pos)>70&&enemies.every(e=>e.hp<=0||distance(e,pos)>e.r+r+8))choices.push({pos,d:distance(origin,pos)});}choices.sort((a,b)=>a.d-b.d);return choices[0]?.pos||center(12,2);}
function spawnEnemy(type,pos,elite=false,summoned=false){const boss=type==='boss',profile=bossProfiles[floor-1]||bossProfiles.at(-1),scale=enemyScale(floor),mode=difficulties[difficulty],damageMultiplier=boss?8:floor<=2?8:floor<=4?15:20;const config={crawler:{hp:28,r:12,speed:72,attack:9},brute:{hp:68,r:16,speed:43,attack:17},archer:{hp:35,r:12,speed:48,attack:11},wraith:{hp:42,r:12,speed:98,attack:10},splitter:{hp:57,r:14,speed:62,attack:13},shaman:{hp:49,r:14,speed:42,attack:10},assassin:{hp:39,r:11,speed:116,attack:16},summoner:{hp:64,r:15,speed:38,attack:8},boss:{hp:520,r:27,speed:36,attack:32}}[type]||{hp:28,r:12,speed:72,attack:9};if(!walkable(map,pos.x,pos.y,config.r))pos=safeEnemyPoint(pos,config.r);const health=Math.round(config.hp*scale.health*(elite?1.65:1)*mode.health),lives=boss?profile.lives:1;enemies.push({id:++enemyId,...pos,type,r:config.r,hp:health,maxHp:health,lifeHp:health,lives,totalLives:lives,phase:1,form:boss?profile.forms[0]:'',speed:config.speed+floor*3,attack:Math.round((config.attack*scale.attack+floor*2)*damageMultiplier*mode.damage),damageMultiplier,cd:rand(.65,1.5),skill:boss?2.2:2.5,slow:0,hit:0,boss,elite,summoned,path:[],pathTimer:0,split:false});}
function spawnPoint(){const choices=[];for(let y=2;y<ROWS-2;y++)for(let x=2;x<COLS-2;x++){const pos=center(x,y);if(walkable(map,pos.x,pos.y,24)&&distance(p,pos)>260&&enemies.every(e=>distance(e,pos)>50))choices.push(pos);}return pick(choices)||center(12,2);}
function safeDropPoint(origin){const choices=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++){const pos=center(x,y);if(!walkable(map,pos.x,pos.y,8))continue;const route=findPath(map,p,pos);if(route.length||distance(p,pos)<20)choices.push({pos,d:distance(origin,pos)});}choices.sort((a,b)=>a.d-b.d);return choices[0]?.pos||center(12,14);}
function dropLoot(item,origin){const pos=safeDropPoint(origin);const drop={id:++lootId,...pos,item};drops.push(drop);return drop;}
function normalWaveCount(mode=difficulty){return {easy:4,normal:5,hard:7}[mode]||4;}
function bossWave(){return normalWaveCount()+1;}
function isBossWave(){return wave===bossWave();}
function bossRewardInfo(depth=floor){return depth<=3?{symbol:'◆',name:'史诗装备',desc:'紫色史诗战利品已经显现',color:'#c18cff'}:depth===4?{id:'life',key:'4',symbol:'♥',name:'赤月生命圣器',desc:'按 4 释放：一次性恢复全部生命',color:'#ef6f70'}:depth===5?{id:'aegis',key:'5',symbol:'◴',name:'停滞神徽',desc:'按 5 释放：一次性获得 5 秒无敌',color:'#7eddf2'}:{symbol:'♜',name:'王座碎片',desc:'可在主界面重铸最后的王座',color:'#f0c76e'};}
function grantBossReward(){const info=bossRewardInfo();if(floor<=3){dropLoot(makeItem(floor,3),center(12,5));log(`${bossNames[floor-1]}留下了一件紫色史诗装备。`);}else if(floor===4){p.artifacts.push({...info,used:false});ring(p.x,p.y,82,info.color,6);log('获得神器“赤月生命圣器”：按 4 主动释放，本局仅可使用一次。');}else if(floor===5){p.artifacts.push({...info,used:false});ring(p.x,p.y,82,info.color,6);log('获得神器“停滞神徽”：按 5 主动释放，本局仅可使用一次。');}else{profile.throneFragments++;saveProfile('王座碎片保存');log(`获得王座碎片，当前持有 ${profile.throneFragments} 枚。`);}return info;}
function useArtifact(id){if(!canAct())return false;if(cleared){toast('神器只能在战斗中释放。');return false;}const artifact=(p.artifacts||[]).find(item=>item.id===id);if(!artifact){toast(id==='life'?'尚未获得赤月生命圣器。':'尚未获得停滞神徽。');return false;}if(artifact.used){toast(`${artifact.name}已经耗尽。`);return false;}if(id==='life'){if(p.hp>=p.maxHp){toast('生命已满，圣器没有被消耗。');return false;}p.hp=p.maxHp;artifact.used=true;ring(p.x,p.y,100,artifact.color,7);burst(p.x,p.y,artifact.color,36);flash('#d64e55',.09);log('赤月生命圣器释放：生命完全恢复，神器已经耗尽。');}else if(id==='aegis'){p.invuln=Math.max(p.invuln,5);artifact.used=true;ring(p.x,p.y,118,artifact.color,8);rune(p.x,p.y,88,artifact.color);flash('#8beaff',.07);log('停滞神徽释放：获得 5 秒绝对无敌，神器已经耗尽。');}else return false;tone(id==='life'?190:680,.3,id==='life'?'sawtooth':'sine',.045);updateUI();return true;}
function startBossDefeatCG(){const info=bossRewardInfo(),origin=lastBossDefeat||center(12,3);cinematic={time:0,duration:5.8,x:origin.x,y:origin.y,color:bossProfiles[floor-1]?.color||'#e7bc6c',boss:bossNames[floor-1],reward:info,depth:floor};screenShake=14;flash('#fff0c5',.3);tone(90,.65,'sawtooth',.055);}
function finishBossDefeatCG(){if(!cinematic)return;cinematic=null;settleWave(true);}
function updateBossDefeatCG(dt){if(!cinematic)return;cinematic.time+=dt;if(cinematic.time>=cinematic.duration)finishBossDefeatCG();}
function settleWave(bossBattle=false){p.gold+=20+floor*10;shopVisits++;refreshCount=0;generateStock();if(bossBattle){grantBossReward();p.potions++;}commitRunProgress();banner(bossBattle?'首领已陨落 · 战利品显现':'战场肃清 · 商人抵达');log(`战斗奖励 +${20+floor*10} 金币。荣誉进度已自动保存。按 B 访问商店。`);if(bossBattle&&floor===6){for(const d of [...drops])collect(d);endRun(true);}updateUI();}
function nextWave(){cleared=false;wave++;roomKind=pick(roomPools[floor-1]||roomPools.at(-1));map=createMap(floor,roomKind);Object.assign(p,center(12,14));p.secondWindUsed=false;path=[];target=null;shots=[];hazards=[];eliteRound=eliteNext;eliteNext=false;const bossBattle=isBossWave();if(bossBattle){spawnEnemy('boss',center(12,3));for(let i=0;i<Math.min(7,floor+1);i++)spawnEnemy(i%3===0?'brute':i%2?'archer':'crawler',spawnPoint(),floor>=5&&i===0);banner(`${rooms[roomKind].name} · ${bossNames[floor-1]}`);}else{const pools=enemyPools[floor-1]||enemyPools.at(-1),count=6+floor*2+Math.min(wave,4);for(let i=0;i<count;i++){let type=pick(pools);if(floor>=2&&wave>=2&&i===0)type='splitter';if(floor>=3&&i===1)type='shaman';if(floor>=3&&wave>=2&&i===2)type='assassin';if(floor>=3&&wave%2===1&&i===0)type='summoner';const depthElite=floor>=4&&i<floor-3;spawnEnemy(type,spawnPoint(),eliteRound&&i<2||depthElite);}banner(`第 ${floor} 层 · ${rooms[roomKind].name} · ${eliteRound?'精英试炼':`普通战斗 ${wave} / ${normalWaveCount()}`}`);}log(bossBattle?`${bossNames[floor-1]}苏醒了，房间：${rooms[roomKind].name}。`:`${rooms[roomKind].name}：第 ${wave} 场普通战斗开始。`);}
function finishWave(){cleared=true;shots=[];hazards=[];target=null;path=[];if(isBossWave()){startBossDefeatCG();return;}settleWave(false);}
function proceed(){if(!cleared||!canAct())return;for(const d of [...drops])collect(d);if(isBossWave()){floor++;wave=0;map=createMap(floor);Object.assign(p,center(12,14));p.hp=Math.min(p.maxHp,p.hp+350);log('进入下一层，恢复 350 生命。');}nextWave();updateUI();}
function addUniqueSupreme(slot,used){let item=null;for(let tries=0;tries<30;tries++){const candidate=makeSupremeItem(floor,slot);if(!used.has(candidate.name)){item=candidate;break;}}if(item){used.add(item.name);stock.push(item);}}
function generateStock(){const owned=new Set([...Object.values(p.equipment),...(p.weapons||[]),...p.inventory].filter(Boolean).map(item=>item.name)),used=new Set(owned);stock=[];for(let i=0;i<4;i++){let item=null;for(let tries=0;tries<80;tries++){const roll=Math.random(),candidate=makeItem(floor,roll<.18?3:roll<.72?2:1);if(!used.has(candidate.name)){item=candidate;break;}}item??=makeItem(floor,i%3+1);if(used.has(item.name))item.name+=`·${['猎手','守望','余烬','秘仪'][i]}`;used.add(item.name);stock.push(item);}if(p.relicSlot){const relic=makeRelic(used);used.add(relic.name);stock.push(relic);}let golden=null;for(let tries=0;tries<30;tries++){const candidate=makeGoldenItem(floor);if(!used.has(candidate.name)){golden=candidate;break;}}if(golden){used.add(golden.name);stock.splice(Math.floor(Math.random()*(stock.length+1)),0,golden);}if(floor>=4)addUniqueSupreme('weapon',used);if(floor>=5)addUniqueSupreme('armor',used);if(floor>=6)addUniqueSupreme('ring',used);}
function lowTierSale(){const sold=p.inventory.filter(item=>item.rarity<=1),value=sold.reduce((sum,item)=>sum+price(item,true),0);if(!sold.length){toast('背包中没有普通或精良装备。');return;}p.inventory=p.inventory.filter(item=>item.rarity>1);p.gold+=value;log(`批量出售 ${sold.length} 件低阶装备，获得 ${value} 金。`);tone(560,.12);showShop('sell');updateUI();}
function showShop(tab='buy'){if(!cleared){toast('清理本场所有敌人后，商人才会出现。');return;}shopTab=tab;const weapon=p.equipment.weapon,enhance=weapon.enhance||0,cost=45+enhance*35,lowItems=p.inventory.filter(item=>item.rarity<=1),lowValue=lowItems.reduce((sum,item)=>sum+price(item,true),0);openModal('shop',`<div class="modal-eyebrow">THE WANDERING MERCHANT · 第 ${shopVisits} 次相逢</div><h2 class="modal-title">烛火商会 <span class="gold" style="font-size:21px;letter-spacing:0">${p.gold} 金</span></h2><p class="modal-subtitle">货架每场战斗更新。购买后进入背包，装备需手动更换。<br>离开时未拾取的战利品会自动收入背包。</p><div class="modal-actions" style="justify-content:flex-start;margin:0 0 18px"><button data-shop="buy" ${tab==='buy'?'class="primary"':''}>购买装备</button><button data-shop="sell" ${tab==='sell'?'class="primary"':''}>背包 / 出售</button><button data-shop="forge" ${tab==='forge'?'class="primary"':''}>锻造 / 补给</button></div>${tab==='buy'?`<div class="inventory-grid">${stock.map((item,i)=>item?itemCard(item,i,'buy'):'<div class="item-card empty">已售出</div>').join('')}</div><div class="modal-actions"><button data-action="refresh" ${p.gold<15+refreshCount*10?'disabled':''}>刷新货架 · ${15+refreshCount*10} 金</button></div>`:tab==='sell'?`<div class="bulk-sale-bar"><div><strong>快速清理行囊</strong><small>仅出售普通与精良装备，不影响已装备物品</small></div><button data-action="sell-low" ${lowItems.length?'':'disabled'}>一键出售 ${lowItems.length} 件 · ${lowValue} 金</button></div><div class="inventory-grid">${p.inventory.length?p.inventory.map((item,i)=>itemCard(item,i,'sell')).join(''):'<p class="empty">背包空空如也。已装备的物品不会被出售。</p>'}</div>`:`<div class="shop-grid"><button data-action="forge" ${p.gold<cost||enhance>=5?'disabled':''}>强化当前武器 +${enhance} → +${Math.min(enhance+1,5)}<span>${enhance>=5?'已满级':`${cost} 金 · 攻击 +5`}</span></button><button data-action="buy-potion" ${p.gold<22||p.potions>=9?'disabled':''}>生命药水（恢复 50% 最大生命）<span>22 金 · 持有 ${p.potions}/9</span></button><button data-action="heal" ${p.gold<18||p.hp>=p.maxHp?'disabled':''}>营火治疗 · 恢复全部生命<span>18 金</span></button><button data-action="vitality" ${p.gold<240?'disabled':''}>坚韧祝福 · 本局最大生命 +200<span>240 金 · 同时恢复 200</span></button></div><p class="modal-note">强化绑定当前武器，最高 +5；换装后旧武器仍保留强化。出售仅返还部分价值。</p>`}<div class="modal-actions"><button data-action="close">返回战场</button><button class="primary" data-action="leave-shop">${wave===3?'进入下一层':'继续战斗'} →</button></div>${wave<2?`<p class="modal-note"><label><input id="elite-choice" type="checkbox" ${eliteNext?'checked':''}> 下一场挑战精英：前两只怪物生命 +50%，击杀赏金 +50%，精英必掉稀有装备</label></p>`:''}`);}
function showInventory(){openModal('inventory',`<div class="modal-eyebrow">YOUR COLLECTION · ${p.inventory.length} / 40</div><h2 class="modal-title">拾荒者行囊</h2><p class="modal-subtitle">更换装备会把旧装备放回背包。战斗已暂停。<br>剩余物品可以在战后商店出售；背包满时战利品留在地上。</p><div class="inventory-grid">${p.inventory.length?p.inventory.map((item,i)=>itemCard(item,i,'inventory')).join(''):'<p class="empty">暂无装备。击败敌人或打开宝箱寻找战利品。</p>'}</div><div class="modal-actions">${cleared?'<button data-shop="sell">前往商店</button>':''}<button class="primary" data-action="close">返回战场</button></div>`);}
function equip(index){const item=p.inventory[index];if(!item)return;if(item.slot==='weapon'){const active=p.equipment.weapon;if(!p.weapons[1]){p.weapons[1]=item;p.inventory.splice(index,1);log(`${item.name}已放入副武器栏，按 3 切换。`);}else{p.inventory.splice(index,1);p.weapons[p.weaponIndex]=item;p.equipment.weapon=item;p.inventory.push(active);log(`切换装备：${item.name}成为当前武器。`);}tone(540);updateUI();if(currentModal==='shop')showShop(shopTab);else showInventory();return;}const old=p.equipment[item.slot];p.equipment[item.slot]=item;p.inventory.splice(index,1);if(old)p.inventory.push(old);log(`装备了${item.name}。`);tone(540);updateUI();if(currentModal==='shop')showShop(shopTab);else showInventory();}
function switchWeapon(){if(!canAct())return;if(!p.weapons?.[1]){toast('还没有副武器，先从战利品或商店获得一把武器。');return;}p.weaponIndex=p.weaponIndex===0?1:0;p.equipment.weapon=p.weapons[p.weaponIndex];path=[];target=null;$('weapon-label').textContent=`${p.equipment.weapon.name} · ${p.equipment.weapon.kind==='sword'?'近战':'远程'}`;toast(`切换至${p.equipment.weapon.name} · ${p.equipment.weapon.kind==='sword'?'近战':'远程'}`);tone(520,.1);updateUI();}
const talentPool=[{id:'power',name:'锋刃',desc:'永久增加本局 5 点攻击'},{id:'vigor',name:'铁心',desc:'最大生命 +250，并恢复 250 生命'},{id:'crit',name:'鹰眼',desc:'暴击率增加 6%'},{id:'leech',name:'汲魂',desc:'命中吸血增加 2%'},{id:'armor',name:'石肤',desc:'护甲增加 3 点'},{id:'haste',name:'疾行',desc:'移动速度增加 8%'},{id:'arcane',name:'奥术蓄能',desc:'最大法力 +20，法力回复 +0.6 / 秒'},{id:'overflow',name:'溢能核心',desc:'法力全满时，主动技能伤害 +30%'},{id:'bloodlust',name:'血战本能',desc:'生命低于 50% 时，造成伤害 +25%'},{id:'executioner',name:'处决印记',desc:'对生命低于 35% 的敌人伤害 +45%'},{id:'secondwind',name:'绝境回响',desc:'每场战斗首次濒死时，恢复 35% 生命与 25 法力'},{id:'alchemy',name:'炼金血脉',desc:'生命药水治疗 +35%，并额外恢复 18 法力'},{id:'echo',name:'技能回响',desc:'释放技能后，下一次普通攻击伤害 +40%'},{id:'thorns',name:'荆棘外壳',desc:'受到近战伤害时反弹 25% 伤害'},{id:'focus',name:'猎手专注',desc:'连续命中同一目标，伤害最多提高 30%'},{id:'unstable',name:'不稳定核心',desc:'技能消耗 +20%，但技能伤害 +45%'},{id:'manaOnCrit',name:'星火回流',desc:'每次暴击恢复 2 点法力'},{id:'manaOnKill',name:'灵魂收割',desc:'每次击杀恢复 4 点法力'}];
function talentScreen(){const available=talentPool.filter(t=>!p.talents?.includes(t.id));const talents=(available.length>=3?available:talentPool).sort(()=>Math.random()-.5).slice(0,3);openModal('talent',`<div class="modal-eyebrow">LEVEL ${p.level} · CHOOSE YOUR PATH</div><h2 class="modal-title">深渊的馈赠</h2><p class="modal-subtitle">本次升级已获得全属性提升，现在从三种构筑天赋中选择一项。</p><div class="weapon-grid">${talents.map(t=>`<button class="weapon-choice" data-talent="${t.id}"><span class="weapon-symbol">✧</span><strong>${t.name}</strong><small>${t.desc}</small></button>`).join('')}</div>`);}
function applyTalent(id){if(!p.talents.includes(id))p.talents.push(id);if(id==='power')p.bonusAttack+=5;if(id==='vigor'){p.maxHp+=250;p.hp=Math.min(p.maxHp,p.hp+250);}if(id==='crit')p.bonusCrit+=6;if(id==='leech')p.bonusLeech+=4;if(id==='armor')p.bonusArmor+=3;if(id==='haste')p.bonusSpeed+=.08;if(id==='arcane'){p.maxMana+=20;p.mana=Math.min(p.maxMana,p.mana+20);p.manaRegen+=.6;}if(id==='secondwind')p.secondWindUsed=false;}
function addXP(amount){p.xp+=amount;while(p.xp>=p.xpGoal){p.xp-=p.xpGoal;p.level++;p.xpGoal=Math.round(p.xpGoal*1.5+10);p.maxHp+=120;p.hp=Math.min(p.maxHp,p.hp+120);p.bonusAttack+=2;p.bonusArmor+=1;p.bonusCrit+=1;p.bonusLeech+=1;p.bonusSpeed+=.02;p.maxMana+=6;p.mana=Math.min(p.maxMana,p.mana+6);p.manaRegen+=.18;pendingTalents++;log(`升至等级 ${p.level}：全属性提升，等待天赋选择。`);}}
function collect(drop){if(!drops.includes(drop))return;if(p.inventory.length>=40){toast('背包已满，请在商店出售装备。');return;}p.inventory.push(drop.item);drops.splice(drops.indexOf(drop),1);log(`拾取 ${rarities[drop.item.rarity].name} · ${drop.item.name}`);textEffect(drop.x,drop.y-15,drop.item.name,rarities[drop.item.rarity].color);tone(750,.09);}
function bossPhase(e){e.lives--;if(e.lives<=0){e.hp=0;return false;}const profile=bossProfiles[floor-1]||bossProfiles.at(-1);e.phase=(e.phase||1)+1;if(floor===6&&e.phase>=MIRROR_PHASE)enterMirrorForm(e);else{e.form=profile.forms[(e.phase-1)%profile.forms.length];e.maxHp=Math.round(e.lifeHp*(1+(e.phase-1)*.11));e.hp=e.maxHp;e.attack+=Math.round((4+floor*1.5)*8);e.speed=Math.min(118,e.speed+4+floor*.5);e.skill=floor>=4?.7:1.05;e.cd=.5;}shots=[];hazards=[];screenShake=12;const color=e.mirror?weaponColor(p.equipment.weapon):profile.color;burst(e.x,e.y,color,52);ring(e.x,e.y,72,color,6);ring(e.x,e.y,122,'#ffffff',2);rune(e.x,e.y,105,color);flash(color,.2);banner(`${profile.name} · ${e.form} · 第 ${e.phase} 命`);log(e.mirror?`深渊剥下你的影子：第 ${e.phase} 命复制你的全部攻击，生命与伤害均为 ${difficulties[difficulty].mirror} 倍！`:`${profile.name}变形为「${e.form}」，第 ${e.phase} 命苏醒！`);return true;}
function harmEnemy(e,amount,critical=false){if(e.hp<=0)return;e.hp-=amount;e.hit=.12;textEffect(e.x+rand(-8,8),e.y-20,`${critical?'暴击 ':''}${Math.round(amount)}`,critical?'#f3d785':'#d4e6d8');burst(e.x,e.y,e.type==='wraith'?'#ae97dc':e.type==='shaman'?'#82d4b0':'#adb789',critical?9:4);if(e.boss){const color=bossProfiles[floor-1]?.color||'#efbd72';ring(e.x,e.y,e.r+18,color,critical?5:3);ring(e.x,e.y,e.r+34,'#fff0bd',critical?3:1);burst(e.x,e.y,color,critical?26:14);if(critical)rune(e.x,e.y,e.r+44,'#ffe29a');screenShake=Math.max(screenShake,critical?5:2);}if(critical){ring(e.x,e.y,28,'#f6dc8b',2);flash('#f6dc8b',.035);}if(p.talents?.includes('focus')){if(p.comboTarget===e.id&&p.comboTimer>0)p.comboBonus=Math.min(.3,(p.comboBonus||0)+.04);else{p.comboTarget=e.id;p.comboBonus=0;}p.comboTimer=2.5;}const stats=playerStats(p),relic=p.equipment.relic||{};p.hp=Math.min(p.maxHp,p.hp+amount*stats.leech*leechDifficultyMultiplier()/100);if(critical&&p.talents?.includes('manaOnCrit'))p.mana=Math.min(p.maxMana,p.mana+2);if(e.hp<=0){if(e.boss&&amount<90000&&e.lives>1){bossPhase(e);return;}e.hp=0;p.kills++;const killMana=(p.talents?.includes('manaOnKill')?4:0)+(relic.killMana||0);if(killMana)p.mana=Math.min(p.maxMana,p.mana+killMana);const coins=Math.round((e.boss?75:rand(5,11))*(1+floor*.18)*(eliteRound?1.5:1)*(1+(p.goldBonus||0)+(relic.goldBonus||0)));p.gold+=coins;addXP(e.boss?75:10+floor*3);burst(e.x,e.y,e.boss?'#f4c384':'#6d9682',e.boss?54:14);if(e.elite||e.boss)rune(e.x,e.y,e.boss?92:42,e.boss?'#efb27b':'#c9a8e8');if(e.type==='splitter'&&!e.split){for(let i=0;i<2;i++)spawnEnemy('crawler',{x:e.x+rand(-25,25),y:e.y+rand(-25,25)},false,true);log('裂壳怪碎裂成两只幼体！');}if(!e.summoned&&(e.elite||Math.random()<.28+(p.lootBonus||0)+(relic.lootBonus||0)))dropLoot(makeItem(floor,e.elite?2:null),{x:e.x,y:e.y});if(e.boss){lastBossDefeat={x:e.x,y:e.y};screenShake=7;flash('#f2bd7c',.12);log(`${bossNames[floor-1]}被彻底击败！`);}if(target===e)target=null;}}
const bossMoveNames={mark:'覆地重压',shards:'裂壳飞棘',charge:'狂暴冲撞',cross:'十字剑气',summon:'深渊唤从',ring:'死亡轮舞',aimed:'追猎星弹',meteor:'陨星坠落',rifts:'三重裂口',teleport:'虚空换位',devour:'血肉吞噬',toxic:'腐血喷泉',boneRing:'万骨环爆',storm:'终焉风暴',rewind:'逆流回溯',clone:'时光分身',stasis:'停滞领域',sword:'裁决横斩',bow:'逐日箭雨',staff:'星铸爆裂'};
function bossProjectile(e,angle,speed,damage,color,r=7){shots.push({x:e.x,y:e.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r,life:4.5,damage,friendly:false,color});}
function isMirrorBoss(e){return floor===6&&e.boss&&(e.phase||1)>=MIRROR_PHASE;}
function mirrorLoadout(e){const stats=playerStats(p),item=p.equipment.weapon,mult=difficulties[difficulty].mirror;e.mirror=true;e.r=p.r;e.mirrorKind=item.kind;e.form=`你的倒影 · ${weaponInfo[item.kind].name}`;e.attack=Math.round(stats.attack*stats.weapon.power*mult);e.speed=Math.round(155*stats.weapon.speed*(1+(p.bonusSpeed||0))*(p.globalStatMultiplier||1)*1.2);}
function enterMirrorForm(e){mirrorLoadout(e);e.maxHp=Math.round(p.maxHp*difficulties[difficulty].mirror);e.hp=e.maxHp;e.lifeHp=e.maxHp;e.cd=.45;e.skill=.85;e.attackAnim=0;e.mirrorMove=Math.max(0,(e.phase||MIRROR_PHASE)-MIRROR_PHASE);e.mirrorCd={dash:1.1,spin:2.4,frost:4};}
function mirrorProjectile(e,angle,mult=1){const item=p.equipment.weapon,rarity=item.rarity||0,magic=item.kind==='staff';shots.push({x:e.x,y:e.y,vx:Math.cos(angle)*(460+rarity*18),vy:Math.sin(angle)*(460+rarity*18),r:(magic?7:5)+Math.floor(rarity/2),life:1.05,damage:e.attack*mult,friendly:false,mirror:true,magic,color:weaponColor(item),rarity});}
function mirrorBasicAttack(e){mirrorLoadout(e);const item=p.equipment.weapon,w=playerStats(p).weapon,angle=Math.atan2(p.y-e.y,p.x-e.x);e.facing=angle;e.attackAnim=.22;if(item.kind==='sword'){effects.push({type:'slash',x:e.x,y:e.y,angle,life:.18,max:.18,r:78+(item.rarity||0)*4,color:weaponColor(item),rarity:item.rarity||0});if(distance(p,e)<=w.range+p.r+e.r&&lineOfSight(map,e,p))hitPlayer(e.attack,e);}else mirrorProjectile(e,angle,1);e.cd=w.delay*.8;}
function mirrorCast(e){mirrorLoadout(e);e.mirrorCd??={dash:0,spin:0,frost:0};const order=['dash','spin','frost'],name=order.map((key,i)=>order[(i+(e.mirrorMove||0))%3]).find(key=>e.mirrorCd[key]<=0);if(!name){e.skill=.28;return;}e.mirrorMove=(order.indexOf(name)+1)%3;e.mirrorCd[name]=(name==='dash'?4.2:name==='spin'?9:13)*.8;e.skill=.55;const item=p.equipment.weapon,kind=item.kind,color=weaponColor(item),angle=Math.atan2(p.y-e.y,p.x-e.x);e.facing=angle;log(`你的倒影施展「${classSkills[kind][name].name}」！`);if(name==='dash'){for(let i=0;i<8;i++){effects.push({type:'ghost',x:e.x,y:e.y,facing:e.facing,mirror:true,life:.3,max:.3});moveBody(map,e,Math.cos(angle)*15,Math.sin(angle)*15);}if(kind==='sword'&&distance(p,e)<55&&lineOfSight(map,e,p))hitPlayer(e.attack*.65,e);if(kind==='bow')for(const spread of [-.18,0,.18])mirrorProjectile(e,angle+spread,.55);ring(e.x,e.y,kind==='staff'?48:42,color,3);return;}if(kind==='bow'){const spreads=name==='spin'?[-.39,-.26,-.13,0,.13,.26,.39]:[-.1,0,.1],mult=name==='spin'?.5:.72;for(const spread of spreads)mirrorProjectile(e,angle+spread,mult);ring(e.x,e.y,name==='spin'?105:82,color,3);return;}const radius=kind==='sword'?(name==='frost'?115:125):(name==='frost'?165:130),power=kind==='sword'?(name==='frost'?1.2:1.75):(name==='frost'?1.05:1.65);bossHazard(e.x,e.y,radius,e.attack*power,color,classSkills[kind][name].name,.62);rune(e.x,e.y,radius*.55,color);}
function bossVolley(e,count,speed,damage,color,offset=0){for(let i=0;i<count;i++)bossProjectile(e,i*Math.PI*2/count+offset,speed,damage,color);ring(e.x,e.y,64,color,3);}
function bossHazard(x,y,r,damage,color,labelText='闪避！',life=1.15,mana=0,extra={}){hazards.push({kind:'circle',x:clamp(x,65,975),y:clamp(y,65,655),r,life,max:life,damage,color,label:labelText,mana,...extra});}
function bossLine(x,y,angle,length,width,damage,color,labelText='直线攻击！',life=.9,extra={}){hazards.push({kind:'line',x,y,angle,length,width,r:width,life,max:life,damage,color,label:labelText,...extra});}
function bossCone(x,y,angle,range,arc,damage,color,labelText='扇形攻击！',life=.9,extra={}){hazards.push({kind:'cone',x,y,angle,range,arc,r:range,life,max:life,damage,color,label:labelText,...extra});}
function pointSegmentDistance(point,x1,y1,x2,y2){const vx=x2-x1,vy=y2-y1,den=vx*vx+vy*vy,t=den?clamp(((point.x-x1)*vx+(point.y-y1)*vy)/den,0,1):0;return Math.hypot(point.x-(x1+vx*t),point.y-(y1+vy*t));}
function hazardHitsPlayer(h){if(h.kind==='line'){const dx=Math.cos(h.angle)*h.length*.5,dy=Math.sin(h.angle)*h.length*.5;return pointSegmentDistance(p,h.x-dx,h.y-dy,h.x+dx,h.y+dy)<h.width*.5+p.r;}if(h.kind==='cone'){const d=distance(p,h);if(d>h.range+p.r)return false;const delta=Math.atan2(Math.sin(Math.atan2(p.y-h.y,p.x-h.x)-h.angle),Math.cos(Math.atan2(p.y-h.y,p.x-h.x)-h.angle));return Math.abs(delta)<h.arc*.5;}return distance(p,h)<h.r+p.r;}
function bossCharge(e,power=1.35){const start={x:e.x,y:e.y},angle=Math.atan2(p.y-e.y,p.x-e.x);for(let i=0;i<9;i++)moveBody(map,e,Math.cos(angle)*16,Math.sin(angle)*16);const length=Math.max(60,distance(start,e));bossLine((start.x+e.x)/2,(start.y+e.y)/2,angle,length,54,e.attack*power,'#ef9a72','冲锋路径！',.58);ring(e.x,e.y,46,'#f0b078',4);}
function bossTeleport(e,color){const old={x:e.x,y:e.y},dest=spawnPoint();Object.assign(e,dest);ring(old.x,old.y,42,color,3);ring(e.x,e.y,52,color,4);rune(e.x,e.y,38,color);}
function bossSummon(e,count=2){if(enemies.filter(other=>other.hp>0).length>=22)return;const pool=floor>=5?['assassin','summoner','wraith']:floor>=3?['wraith','splitter','shaman']:['crawler','archer'];for(let i=0;i<count;i++)spawnEnemy(pick(pool),{x:e.x+rand(-75,75),y:e.y+rand(-60,60)},floor>=5&&i===0,true);}
function castBossMove(e,move){const profile=bossProfiles[floor-1]||bossProfiles.at(-1),phase=e.phase||1,color=profile.color,angle=Math.atan2(p.y-e.y,p.x-e.x),damage=e.attack*(1+phase*.045);
  if(move==='mark')bossHazard(p.x,p.y,88+floor*5,damage*1.35,color,'碎地！');
  if(move==='shards')bossVolley(e,10+phase*2,165+phase*12,damage*.55,color,elapsed*.15);
  if(move==='charge')bossCharge(e,1.25+phase*.05);
  if(move==='cross'){bossLine(p.x,p.y,phase%2?0:Math.PI/4,560,46,damage*.9,color,'十字斩！',.95);bossLine(p.x,p.y,(phase%2?0:Math.PI/4)+Math.PI/2,560,46,damage*.9,color,'十字斩！',.95);}
  if(move==='summon')bossSummon(e,Math.min(4,1+Math.ceil(phase/3)));
  if(move==='ring')bossVolley(e,12+phase*2,155+phase*13,damage*.58,color,elapsed*.22);
  if(move==='aimed'){bossCone(e.x,e.y,angle,350,.72,damage*.9,color,'星弹扇面！',.82);for(let i=-3;i<=3;i++)bossProjectile(e,angle+i*.12,245+floor*10,damage*.68,color,6);}
  if(move==='meteor')for(let i=0;i<3+Math.ceil(floor/2);i++)bossHazard(p.x+rand(-165,165),p.y+rand(-135,135),52+phase*2,damage*1.15,color,'陨星！',1.28);
  if(move==='rifts')for(let i=-1;i<=1;i++)bossLine(p.x+Math.cos(angle+Math.PI/2)*i*92,p.y+Math.sin(angle+Math.PI/2)*i*92,angle,460,38+phase*2,damage,color,'裂口墙！',1.25);
  if(move==='teleport'){bossTeleport(e,color);bossVolley(e,8,205,damage*.55,color,Math.PI/8);}
  if(move==='devour'){e.hp=Math.min(e.maxHp,e.hp+e.maxHp*.045);textEffect(e.x,e.y-32,'吞噬恢复','#ff9c9c');burst(e.x,e.y,color,24);bossSummon(e,2);}
  if(move==='toxic')for(let i=0;i<5;i++)bossHazard(p.x+rand(-180,180),p.y+rand(-145,145),38+phase,damage*.72,'#8ed47f','腐血地雷！',1.45,0,{burst:8,burstSpeed:175});
  if(move==='boneRing'){bossVolley(e,10+phase,175,damage*.48,'#f0d6b0');bossVolley(e,8+phase,235,damage*.42,color,Math.PI/(8+phase));}
  if(move==='storm'){bossVolley(e,14+phase,185+phase*8,damage*.46,color,elapsed*.25);for(let i=-2;i<=2;i++)bossLine(520+i*145,360,Math.PI/2,590,34,damage*.8,color,'风暴切线！',.75+i*.08);}
  if(move==='rewind'){e.hp=Math.min(e.maxHp,e.hp+e.maxHp*.05);bossTeleport(e,color);textEffect(e.x,e.y-34,'时间回溯','#9ee9f4');}
  if(move==='clone'){bossSummon(e,3);bossVolley(e,8,220,damage*.5,color,Math.PI/8);}
  if(move==='stasis')bossHazard(p.x,p.y,118,damage*.85,color,'法力停滞！',1.45,24);
  if(move==='sword')bossCone(e.x,e.y,angle,175,1.7,damage*1.55,'#ffd66e','裁决横斩！',.72);
  if(move==='bow'){for(let i=-4;i<=4;i++){const x=clamp(p.x+i*54,55,985);bossLine(x,360,Math.PI/2,590,24,damage*.58,'#ffd66e','箭雨轨迹！',.62+Math.abs(i)*.055,{arrows:1});}}
  if(move==='staff'){for(let i=0;i<3;i++)bossLine(p.x,p.y,elapsed*.4+i*Math.PI/3,460,42,damage,'#c6a4ff','星铸棱镜！',1.08);bossVolley(e,8,195,damage*.48,'#ffd66e',Math.PI/8);}
  ring(e.x,e.y,34,color,3);log(`${profile.name}施展「${bossMoveNames[move]}」！`);
}
function bossCast(e){if(isMirrorBoss(e)){mirrorCast(e);return;}const profile=bossProfiles[floor-1]||bossProfiles.at(-1),phase=e.phase||1,offset=Math.random()<.55?0:Math.floor(Math.random()*profile.moves.length),move=profile.moves[(phase-1+offset)%profile.moves.length];e.skill=Math.max(.9,4.45-floor*.3-phase*.14);castBossMove(e,move);if(floor>=4&&phase>=5&&Math.random()<.4){const second=profile.moves[(phase+2)%profile.moves.length];if(second!==move)castBossMove(e,second);}}
function hitPlayer(amount,source=null){if(p.invuln>0||p.hp<=0)return;const relic=p.equipment.relic||{},armor=playerStats(p).armor,mitigation=100/(100+armor*2),damage=Math.max(2,Math.round(amount*(p.buffs?.ward>0?.5:1)*mitigation*(1-(relic.damageReduction||0))));p.hp-=damage;p.invuln=.4;screenShake=3;textEffect(p.x,p.y-25,`−${damage}`,'#ff9d88');tone(95,.1,'sawtooth',.025);const thorns=(p.talents?.includes('thorns')?.25:0)+(relic.thorns||0);if(thorns&&source?.hp>0)harmEnemy(source,Math.max(1,Math.round(damage*thorns)));if(p.hp<=0&&p.talents?.includes('secondwind')&&!p.secondWindUsed){p.secondWindUsed=true;p.hp=Math.round(p.maxHp*.35);p.mana=Math.min(p.maxMana,p.mana+25);toast('绝境回响触发！');log('绝境回响救回了你，恢复生命与法力。');return;}if(p.hp<=0){p.hp=0;endRun(false);}}
function damageRoll(mult=1,target=null,normal=false){const stats=playerStats(p),relic=p.equipment.relic||{},crit=Math.random()*100<stats.crit;let amount=stats.attack*stats.weapon.power*mult*(crit?1.75:1)*(p.buffs?.fury>0?1.5:1);if(p.talents?.includes('overflow')&&p.mana>=p.maxMana-.1)amount*=1.3;if(p.talents?.includes('bloodlust')&&p.hp/p.maxHp<.5)amount*=1.25;if(target&&p.talents?.includes('executioner')&&target.hp/target.maxHp<.35)amount*=1.45;if(target?.boss)amount*=1+(relic.bossDamage||0);if(target&&target.hp/target.maxHp<.35)amount*=1+(relic.lowHpDamage||0);if(target&&p.comboTarget===target.id)amount*=1+(p.comboBonus||0);if(normal&&p.nextAttackBonus>0)amount*=p.nextAttackBonus;return {amount,crit};}
function attack(){if(!canAct()||p.cd.attack>0)return;const stats=playerStats(p),w=stats.weapon,kind=p.equipment.weapon.kind,ranged=kind!=='sword';const live=enemies.filter(e=>e.hp>0),visible=live.filter(e=>lineOfSight(map,p,e));const nearest=target?.hp>0&&lineOfSight(map,p,target)?target:(ranged?visible:visible.filter(e=>distance(p,e)<w.range)).sort((a,b)=>distance(p,a)-distance(p,b))[0];if(nearest)p.facing=Math.atan2(nearest.y-p.y,nearest.x-p.x);else p.facing=Math.atan2(aim.y-p.y,aim.x-p.x);p.cd.attack=w.delay*(p.equipment.relic?.cooldownRate||1);tone(kind==='staff'?320:180,.07,'triangle');weaponAttackEffect(p.equipment.weapon);if(kind==='sword'){const rarity=p.equipment.weapon.rarity||0;effects.push({type:'slash',x:p.x,y:p.y,angle:p.facing,life:.18,max:.18,r:78+rarity*4,color:weaponColor(p.equipment.weapon),rarity});if(rarity>=2)effects.push({type:'slash',x:p.x,y:p.y,angle:p.facing+.08,life:.23,max:.23,r:60+rarity*5,color:rarity>=4?'#fff4bd':weaponColor(p.equipment.weapon),rarity});for(const e of live){const ang=Math.atan2(e.y-p.y,e.x-p.x)-p.facing;if(distance(p,e)<=w.range+e.r&&Math.cos(ang)>.05&&lineOfSight(map,p,e)){const d=damageRoll(1,e,true);harmEnemy(e,d.amount,d.crit);weaponImpact(e.x,e.y,p.equipment.weapon);}}}else{const d=damageRoll(1,nearest,true);firePlayerShot(p.facing,d.amount,p.equipment.weapon,kind==='staff');shots.at(-1).crit=d.crit;}p.nextAttackBonus=0;}
function skill(name){if(!canAct()||p.cd[name]>0)return;const info=skillInfoFor(name);if(!info)return;const unstable=p.talents?.includes('unstable');const cost=Math.ceil(info.cost*(unstable?1.2:1));if(p.mana<cost){toast(`法力不足，需要 ${cost} 点法力。`);return;}p.mana-=cost;const kind=p.equipment.weapon.kind;if(name==='dash'){if(!walkable(map,p.x,p.y,p.r))Object.assign(p,center(12,14));p.cd.dash=4.2;p.invuln=.45;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(!dx&&!dy){dx=Math.cos(p.facing);dy=Math.sin(p.facing);}const length=Math.hypot(dx,dy);for(let i=0;i<8;i++){effects.push({type:'ghost',x:p.x,y:p.y,life:.3,max:.3});moveBody(map,p,dx/length*15,dy/length*15);}path=[];if(kind==='sword'){ring(p.x,p.y,42,'#e3b66e',3);for(const e of enemies)if(e.hp>0&&distance(p,e)<55&&lineOfSight(map,p,e)){const d=damageRoll(.65,e);harmEnemy(e,d.amount,d.crit);weaponImpact(e.x,e.y,p.equipment.weapon);}}else if(kind==='bow'){for(const spread of [-.18,0,.18]){const d=damageRoll(.55,null,true);firePlayerShot(p.facing+spread,d.amount,p.equipment.weapon,false);shots.at(-1).crit=d.crit;}}else{ring(p.x,p.y,48,'#a9c8ef',3);rune(p.x,p.y,34,'#9cc9ef');}if(p.talents?.includes('echo'))p.nextAttackBonus=1.4;tone(450,.12);return;}if(kind==='bow'&&name==='spin'){p.cd.spin=9;ring(p.x,p.y,105,'#d3b77a',2);for(let i=0;i<7;i++){const angle=p.facing+(i-3)*.13,d=damageRoll(.5,null,true);firePlayerShot(angle,d.amount,p.equipment.weapon,false);shots.at(-1).crit=d.crit;}burst(p.x,p.y,'#d9b875',18);screenShake=2;tone(260,.2);return;}if(kind==='bow'&&name==='frost'){p.cd.frost=13;const marked=enemies.filter(e=>e.hp>0&&lineOfSight(map,p,e)).sort((a,b)=>distance(p,a)-distance(p,b))[0];if(marked){p.facing=Math.atan2(marked.y-p.y,marked.x-p.x);marked.slow=3;for(const spread of [-.1,0,.1]){const d=damageRoll(.72,marked);firePlayerShot(p.facing+spread,d.amount,p.equipment.weapon,false);shots.at(-1).crit=d.crit;}}ring(p.x,p.y,82,'#9dd9ee',3);rune(p.x,p.y,46,'#9dd9ee');flash('#9dd9ee',.045);tone(700,.2);return;}const frost=name==='frost',radius=kind==='sword'?(frost?115:125):(frost?165:130),power=(kind==='sword'?(frost?1.2:1.75):(frost?1.05:1.65))*(unstable?1.45:1);p.cd[name]=frost?13:9;const color=kind==='staff'?(frost?'#80dfe3':'#b995e8'):(frost?'#9ebed0':'#efcb8b');ring(p.x,p.y,radius,color,5);ring(p.x,p.y,radius*.68,frost?'#c2f5f4':'#fff0ad',2);rune(p.x,p.y,radius*.55,color);burst(p.x,p.y,frost?'#84dce3':'#e4bb78',32);flash(frost?'#83dce3':'#e8bf78',.06);for(const e of enemies)if(e.hp>0&&distance(p,e)<radius&&lineOfSight(map,p,e)){const d=damageRoll(power,e);harmEnemy(e,d.amount,d.crit);if(frost)e.slow=kind==='sword'?1.4:2.5;weaponImpact(e.x,e.y,p.equipment.weapon);}if(p.talents?.includes('echo'))p.nextAttackBonus=1.4;screenShake=3;tone(frost?650:135,.2);}
function potion(){if(!canAct())return;if(p.cd.potion>0){toast('药水冷却中。');return;}if(!p.potions){toast('药水用完了，战后商店可以补充。');return;}if(p.hp>=p.maxHp){toast('生命已满。');return;}p.potions--;p.hp=Math.min(p.maxHp,p.hp+p.maxHp*(p.talents?.includes('alchemy')?.675:.5));if(p.talents?.includes('alchemy'))p.mana=Math.min(p.maxMana,p.mana+18);p.cd.potion=3;ring(p.x,p.y,50,'#8cdfaa');textEffect(p.x,p.y-25,'恢复生命','#94e3ac');tone(720,.2);updateUI();}
function interact(){if(!canAct())return;const near=drops.find(d=>distance(p,d)<90);if(near){collect(near);return;}if(cleared){showShop();return;}toast('靠近战利品可自动拾取。');}
function endRun(won){if(runRewarded)return;runRewarded=true;finished=true;running=false;paused=true;p.hp=Math.max(0,p.hp);commitRunProgress('远征结算');const record={won,kills:p.kills,floor,time:Math.round(elapsed),difficulty};if(!best||(won&&!best.won)||(won===best.won&&p.kills>best.kills)){best=record;saveBest();}const baseReward=Math.max(1,(floor-1)*5+(wave-1)*2+Math.floor(p.kills/15)+(won?30:0)),diamonds=Math.max(1,Math.round(baseReward*difficulties[difficulty].reward*(1+(p.diamondBonus||0)))),battleCount=6*(normalWaveCount()+1);profile.diamonds+=diamonds;profile.totalRuns++;profile.totalWins+=won?1:0;profile.bestFloor=Math.max(profile.bestFloor,floor);if(won&&difficulty==='hard')profile.hardWins++;saveProfile('远征结算');updateUI();openModal('result',`<div class="modal-eyebrow">${won?'THE ABYSS REMEMBERS YOUR NAME':'EVERY DESCENT LEAVES A STORY'} · ${difficulties[difficulty].name}</div><h2 class="modal-title">${won?'带着传说归来':'火光暂时熄灭'}</h2><p class="modal-subtitle">${won?`你击败了终焉化身，穿越六层深渊归来。<br>${battleCount} 场战斗与六位变形首领，都将记住你的名字。`:'深渊收下了这次远征，但没有收走你的勇气。<br>越深入敌人越强，留意首领的变形提示并保留药水。'}</p><div class="result-stats"><div><strong>${p.kills}</strong><span>击败敌人</span></div><div><strong>◆ ${diamonds}</strong><span>本局钻石</span></div><div><strong>${formatTime(elapsed)}</strong><span>远征用时</span></div></div><button class="primary wide" data-action="restart">返回主界面 →</button><p class="modal-note">钻石、荣誉与王座碎片已保存；装备、金币、神器和天赋将在新局重置。</p>`);}
function formatTime(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
function pauseScreen(){if(!running||finished)return;if(modal.open){if(['pause','help','inventory','shop'].includes(currentModal))closeModal();return;}openModal('pause','<div class="modal-eyebrow">TAKE A BREATH</div><h2 class="modal-title">营火仍在燃烧</h2><p class="modal-subtitle">远征已暂停。整理思绪，再次出发。</p><button class="primary wide" data-action="close">继续远征</button><div class="modal-actions"><button data-action="help">操作说明</button><button data-action="confirm-restart">重新开始</button></div>');}
function showHelp(){openModal('help',`<div class="modal-eyebrow">FIELD NOTES</div><h2 class="modal-title">冒险指南</h2><p class="modal-subtitle">${difficulties[difficulty].name}难度每层包含 ${normalWaveCount()} 场普通战斗，再迎战会变形的首领。第四层起首领拥有八条命。</p><div class="help-grid"><kbd>WASD / 方向键</kbd><span>移动，立即取消鼠标寻路与自动追击。</span><kbd>鼠标左键</kbd><span>点击地面自动绕行；点击敌人持续追击并攻击。</span><kbd>Space / 右键</kbd><span>普通攻击；法杖与猎弓可跨地图射击，但仍会被墙壁阻挡。</span><kbd>Shift</kbd><span>当前职业的位移技能，短暂无敌且不能穿墙。</span><kbd>1 / 2</kbd><span>长剑、猎弓与法杖拥有不同的专属技能。</span><kbd>4 / 5</kbd><span>释放第四、第五层首领神器；每件每局只能主动使用一次。</span><kbd>Q</kbd><span>喝药恢复 50% 最大生命，有 3 秒冷却。</span><kbd>I / B</kbd><span>打开背包 / 战后商店，自动暂停。</span><kbd>E</kbd><span>拾取附近装备；战后打开商店。走到传送门进入下一场。</span><kbd>Esc</kbd><span>暂停或关闭菜单。升级天赋必须完成选择。</span></div><p class="modal-note">前三层首领必定留下紫色史诗装备；第四层起依次获得神器与王座碎片。<br>首领击败 CG 播放 0.6 秒后可按空格跳过。</p><div class="modal-actions"><button class="primary" data-action="${running?'close':'restart'}">知道了</button></div>`);}
function updateUI(){const stats=playerStats(p);$('chapter').innerHTML=`第${['一','二','三','四','五','六'][floor-1]}层 <span>· ${floorNames[floor-1]}</span>`;$('area-name').textContent=floorNames[floor-1];$('hp-text').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('hp-fill').style.width=`${p.hp/p.maxHp*100}%`;$('mana-text').textContent=`${Math.floor(p.mana)} / ${p.maxMana}`;$('mana-fill').style.width=`${p.mana/p.maxMana*100}%`;$('xp-text').textContent=`${p.xp} / ${p.xpGoal}`;$('xp-fill').style.width=`${p.xp/p.xpGoal*100}%`;$('attack').textContent=stats.attack;$('armor').textContent=stats.armor;$('crit').textContent=`${stats.crit}%`;$('gold').textContent=p.gold;$('level').textContent=`等级 ${p.level}`;$('level-badge').textContent=String(p.level).padStart(2,'0');$('potions').textContent=p.cd.potion>0?`${p.cd.potion.toFixed(1)} 秒 · ${p.potions} 瓶`:`${p.potions} 瓶`;renderPotionTray();$('time').textContent=formatTime(elapsed);$('objective').textContent=!running?(finished?'本次远征已结束':'选择武器，踏入深渊'):cleared?'战场肃清 · B 商店 / 传送门继续':`第 ${wave}/3 场 · 剩余 ${enemies.filter(e=>e.hp>0).length} 个敌人`;for(let i=1;i<=6;i++)$('depth'+i).classList.toggle('active',i===floor);for(const key of ['dash','spin','frost']){$(key+'-cd').textContent=p.cd[key]>0?`${p.cd[key].toFixed(1)} 秒`:'就绪';$(key).classList.toggle('cooling',p.cd[key]>0);}const boss=enemies.find(e=>e.boss&&e.hp>0);$('bossbar').hidden=!boss;if(boss){$('boss-name').textContent=`${bossNames[floor-1]} · ${boss.form||'初始形态'} · ${'◆'.repeat(boss.lives||1)}`;$('boss-health').style.width=`${boss.hp/boss.maxHp*100}%`;}$('equipment').innerHTML=['weapon','armor','ring'].map((slot,i)=>{const item=p.equipment[slot];return `<div class="equip-slot" style="--item:${item?rarities[item.rarity].color:'#728681'}"><span class="equip-icon">${item?itemIcon(item):['†','⛨','◈'][i]}</span><div><strong>${item?item.name+(item.enhance?` +${item.enhance}`:''):['武器','未装备胸甲','未装备指环'][i]}</strong><small>${item?itemStats(item):'探索地牢获取装备'}</small></div></div>`;}).join('');}
function update(dt){
  if(cinematic){updateBossDefeatCG(dt);return;}
  elapsed+=dt;for(const key in p.cd)p.cd[key]=Math.max(0,p.cd[key]-dt);p.invuln=Math.max(0,p.invuln-dt);p.mana=Math.min(p.maxMana,p.mana+((p.manaRegen||0)+(p.equipment.relic?.manaRegen||0))*dt);p.comboTimer=Math.max(0,(p.comboTimer||0)-dt);if(p.comboTimer<=0){p.comboTarget=null;p.comboBonus=0;}repath-=dt;
  let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);
  if(dx||dy){path=[];target=null;const len=Math.hypot(dx,dy);dx/=len;dy/=len;p.facing=Math.atan2(dy,dx);$('mode').textContent='键盘移动';}
  else{if(target?.hp>0){const stats=playerStats(p),melee=p.equipment.weapon.kind==='sword',blocked=!lineOfSight(map,p,target),tooFar=melee&&distance(p,target)>stats.weapon.range*.85;if(tooFar||blocked){if(repath<=0){path=findPath(map,p,target);repath=.3;}}else{path=[];attack();}}if(path.length){let next=path[0],dist=distance(p,next);if(dist<7){path.shift();next=path[0];dist=next?distance(p,next):0;}if(next&&dist>0){dx=(next.x-p.x)/dist;dy=(next.y-p.y)/dist;p.facing=Math.atan2(dy,dx);}}}
  const speed=155*playerStats(p).weapon.speed*(1+(p.bonusSpeed||0))*(p.globalStatMultiplier||1);moveBody(map,p,dx*speed*dt,dy*speed*dt);
  if(keys.has(' ')||held)attack();
  for(const e of enemies){if(e.hp<=0)continue;if(!walkable(map,e.x,e.y,e.r)){Object.assign(e,safeEnemyPoint(e,e.r));e.path=[];e.pathTimer=0;textEffect(e.x,e.y-22,'脱困','#9fe3c2');}const mirror=isMirrorBoss(e);if(mirror)mirrorLoadout(e);e.cd-=dt;e.skill-=dt;e.slow=Math.max(0,e.slow-dt);e.hit=Math.max(0,e.hit-dt);e.attackAnim=Math.max(0,(e.attackAnim||0)-dt);if(e.mirrorCd)for(const key in e.mirrorCd)e.mirrorCd[key]=Math.max(0,e.mirrorCd[key]-dt);e.pathTimer-=dt;const dist=distance(p,e),los=lineOfSight(map,e,p),ranged=mirror?p.equipment.weapon.kind!=='sword':['archer','shaman','summoner'].includes(e.type),stop=mirror&&ranged?Math.min(270,playerStats(p).weapon.range*.78):ranged?235:e.r+p.r+7;
    e.moving=false;if(dist>stop||!los){if(e.pathTimer<=0){e.path=findPath(map,e,p);e.pathTimer=.45+Math.random()*.2;}let dest=los?p:e.path[0];if(dest&&distance(e,dest)<8){e.path.shift();dest=e.path[0]||p;}if(dest){const d=Math.max(1,distance(e,dest));e.facing=Math.atan2(dest.y-e.y,dest.x-e.x);e.moving=true;moveBody(map,e,(dest.x-e.x)/d*e.speed*(e.slow>0?.38:1)*dt,(dest.y-e.y)/d*e.speed*(e.slow>0?.38:1)*dt);}}
    if(mirror&&dist<playerStats(p).weapon.range+e.r+p.r&&los&&e.cd<=0)mirrorBasicAttack(e);
    if(!mirror&&ranged&&dist<330&&los&&e.cd<=0){const a=Math.atan2(p.y-e.y,p.x-e.x),color=e.type==='shaman'?'#7ed5a8':e.type==='summoner'?'#c092e4':'#e6a16d';shots.push({x:e.x,y:e.y,vx:Math.cos(a)*(210+floor*9),vy:Math.sin(a)*(210+floor*9),r:5,life:2.3,damage:e.attack,friendly:false,color});e.cd=Math.max(1.05,1.65-floor*.07);}
    if(!mirror&&!ranged&&dist<e.r+p.r+13&&los&&e.cd<=0){hitPlayer(e.attack,e);e.cd=e.boss?1.2:e.type==='wraith'?.9:1.3;}
    if(e.boss&&e.skill<=0)bossCast(e);
  }
  for(let i=0;i<enemies.length;i++)for(let j=i+1;j<enemies.length;j++){const a=enemies[i],b=enemies[j],d=distance(a,b),min=a.r+b.r;if(a.hp>0&&b.hp>0&&d>0&&d<min){const push=(min-d)*.35;moveBody(map,a,(a.x-b.x)/d*push,(a.y-b.y)/d*push);moveBody(map,b,(b.x-a.x)/d*push,(b.y-a.y)/d*push);}}
  for(const shot of shots){if(shot.life<=0)continue;shot.life-=dt;const steps=Math.ceil(Math.hypot(shot.vx,shot.vy)*dt/6);for(let step=0;step<steps&&shot.life>0;step++){shot.x+=shot.vx*dt/steps;shot.y+=shot.vy*dt/steps;if(!walkable(map,shot.x,shot.y,3)){shot.life=0;burst(shot.x,shot.y,shot.color||(shot.friendly?'#bce0c2':'#e99475'),3);break;}if(shot.friendly){const enemy=enemies.find(e=>e.hp>0&&distance(e,shot)<e.r+shot.r);if(enemy){shot.life=0;harmEnemy(enemy,shot.damage,shot.crit);weaponImpact(shot.x,shot.y,shot.weapon||p.equipment.weapon);if(shot.magic){ring(shot.x,shot.y,58,shot.color||'#92cce6');for(const other of enemies)if(other!==enemy&&other.hp>0&&distance(other,shot)<58&&lineOfSight(map,shot,other))harmEnemy(other,shot.damage*.6);}}}else if(distance(p,shot)<p.r+shot.r){shot.life=0;hitPlayer(shot.damage);}}}
  shots=shots.filter(s=>s.life>0);
  for(const h of hazards){h.life-=dt;if(h.life<=0){const color=h.color||'#ed846b';ring(h.x,h.y,Math.min(h.r||h.width||48,96),color);burst(h.x,h.y,color,h.kind==='line'?12:22);if(hazardHitsPlayer(h)){hitPlayer(h.damage);if(h.mana){p.mana=Math.max(0,p.mana-h.mana);textEffect(p.x,p.y-38,`法力 −${h.mana}`,'#9edff2');}}if(h.burst){for(let i=0;i<h.burst;i++)shots.push({x:h.x,y:h.y,vx:Math.cos(i*Math.PI*2/h.burst)*h.burstSpeed,vy:Math.sin(i*Math.PI*2/h.burst)*h.burstSpeed,r:5,life:3,damage:h.damage*.58,friendly:false,color});}screenShake=5;}}hazards=hazards.filter(h=>h.life>0);
  for(const drop of [...drops]){if(!drop.reachableChecked||!walkable(map,drop.x,drop.y,8)){if(!walkable(map,drop.x,drop.y,8)||(distance(p,drop)>=20&&!findPath(map,p,drop).length))Object.assign(drop,safeDropPoint(drop));drop.reachableChecked=true;}if(distance(p,drop)<25&&p.inventory.length<40)collect(drop);}
  enemies=enemies.filter(e=>e.hp>0);
  if(!enemies.length&&!cleared&&running)finishWave();
  if(cleared&&distance(p,center(12,2))<34&&running)proceed();
  if(pendingTalents>0&&running&&!modal.open&&!cinematic){pendingTalents--;talentScreen();}
}

